use anyhow::Result;
use std::collections::{HashMap, HashSet};
use std::fmt::Write as _;

use super::sanitize_c_ident;
use crate::binary::custom_elf::{infer_field_type_by_name, AdaptiveTypeResolver};
use crate::binary::il2cpp::{read_type_field_offset, RegistrationResult, TypeResolver};
use crate::binary::BinaryImage;
use crate::metadata::adaptive::AdaptiveMetadata;
use crate::metadata::Metadata;

const IL2CPP_BASE_TYPES: &str = "\
// Auto-generated by il2cpp-dumper-rs
#pragma once
#include <stdint.h>

typedef struct Il2CppObject {
    void* klass;
    void* monitor;
} Il2CppObject;

typedef struct Il2CppString {
    Il2CppObject obj;
    int32_t length;
    uint16_t chars[1];
} Il2CppString;

typedef struct Il2CppArrayBounds {
    uintptr_t length;
    int32_t lower_bound;
} Il2CppArrayBounds;

typedef struct Il2CppArray {
    Il2CppObject obj;
    Il2CppArrayBounds* bounds;
    uintptr_t max_length;
} Il2CppArray;

typedef struct Il2CppVector2 {
    float x;
    float y;
} Il2CppVector2;

typedef struct Il2CppVector3 {
    float x;
    float y;
    float z;
} Il2CppVector3;

typedef struct Il2CppVector4 {
    float x;
    float y;
    float z;
    float w;
} Il2CppVector4;

";

/// Map an IL2CPP formatted type name to a C/C++ type string and byte size.
pub fn map_c_type(type_name: &str, ptr_sz: usize) -> (&'static str, usize) {
    let clean = type_name.trim().trim_start_matches("ref ");
    match clean {
        "bool" | "System.Boolean" | "Boolean" => ("uint8_t", 1),
        "sbyte" | "System.SByte" | "SByte" => ("int8_t", 1),
        "byte" | "System.Byte" | "Byte" => ("uint8_t", 1),
        "char" | "System.Char" | "Char" => ("uint16_t", 2),
        "short" | "System.Int16" | "Int16" => ("int16_t", 2),
        "ushort" | "System.UInt16" | "UInt16" => ("uint16_t", 2),
        "int" | "System.Int32" | "Int32" => ("int32_t", 4),
        "uint" | "System.UInt32" | "UInt32" => ("uint32_t", 4),
        "long" | "System.Int64" | "Int64" => ("int64_t", 8),
        "ulong" | "System.UInt64" | "UInt64" => ("uint64_t", 8),
        "float" | "System.Single" | "Single" => ("float", 4),
        "double" | "System.Double" | "Double" => ("double", 8),
        "string" | "System.String" | "String" => ("Il2CppString*", ptr_sz),
        "IntPtr" | "System.IntPtr" => ("intptr_t", ptr_sz),
        "UIntPtr" | "System.UIntPtr" => ("uintptr_t", ptr_sz),
        "Vector2" | "UnityEngine.Vector2" => ("Il2CppVector2", 8),
        "Vector3" | "UnityEngine.Vector3" => ("Il2CppVector3", 12),
        "Vector4" | "UnityEngine.Vector4" | "Quaternion" | "UnityEngine.Quaternion" | "Color"
        | "UnityEngine.Color" => ("Il2CppVector4", 16),
        _ => ("void*", ptr_sz),
    }
}

struct StructFieldEntry {
    offset: usize,
    c_type: &'static str,
    size: usize,
    name: String,
    raw_type: String,
}

fn alloc_unique_struct_name(used: &mut HashSet<String>, base: String, td_idx: usize) -> String {
    if used.insert(base.clone()) {
        return base;
    }
    let with_idx = format!("{}_{}", base, td_idx);
    if used.insert(with_idx.clone()) {
        return with_idx;
    }
    let mut n = 1usize;
    loop {
        let cand = format!("{}_{}", with_idx, n);
        if used.insert(cand.clone()) {
            return cand;
        }
        n += 1;
    }
}

fn emit_padded_struct_fields(
    out: &mut String,
    mut instance_fields: Vec<StructFieldEntry>,
    static_fields: &[(String, String, Option<usize>)],
    is_open_generic: bool,
) {
    for (stype, sname, soff) in static_fields {
        let off_note = soff
            .map(|o| format!(" // 0x{:X}", o))
            .unwrap_or_default();
        let _ = writeln!(out, "    // static /* {} */ {};{}", stype, sname, off_note);
    }

    if instance_fields.is_empty() {
        out.push_str("    uint8_t _empty;\n");
        return;
    }

    instance_fields.sort_by_key(|f| f.offset);
    let mut used_names = HashSet::with_capacity(instance_fields.len());
    let mut unique_names = Vec::with_capacity(instance_fields.len());
    for f in &instance_fields {
        let base = if f.name.is_empty() {
            "field".to_string()
        } else {
            f.name.clone()
        };
        let mut candidate = base.clone();
        let mut idx = 1usize;
        while !used_names.insert(candidate.clone()) {
            candidate = format!("{}_{}", base, idx);
            idx += 1;
        }
        unique_names.push(candidate);
    }

    if is_open_generic && instance_fields.len() > 1 && instance_fields.iter().all(|f| f.offset == 0) {
        out.push_str("    // open generic template (field offsets depend on instantiation)\n");
        for (idx, f) in instance_fields.iter().enumerate() {
            let _ = writeln!(out, "    {} {}; // {}", f.c_type, unique_names[idx], f.raw_type);
        }
        return;
    }

    let mut cursor = 0usize;
    for (idx, f) in instance_fields.iter().enumerate() {
        let uname = &unique_names[idx];
        if f.offset < cursor {
            let _ = writeln!(
                out,
                "    // [overlap @ 0x{:X}] {} {}; // {}",
                f.offset, f.c_type, uname, f.raw_type
            );
            continue;
        }
        if f.offset > cursor {
            let gap = f.offset - cursor;
            let _ = writeln!(out, "    uint8_t _pad_0x{:X}[0x{:X}];", cursor, gap);
        }

        let next_off = instance_fields[idx + 1..]
            .iter()
            .map(|n| n.offset)
            .find(|&o| o > f.offset);
        if let Some(no) = next_off {
            if no < f.offset + f.size {
                let avail = no - f.offset;
                let _ = writeln!(
                    out,
                    "    uint8_t {}[0x{:X}]; // {} @ 0x{:X}",
                    uname, avail, f.raw_type, f.offset
                );
                cursor = f.offset + avail;
                continue;
            }
        }

        let _ = writeln!(
            out,
            "    {} {}; // {} @ 0x{:X}",
            f.c_type, uname, f.raw_type, f.offset
        );
        cursor = f.offset + f.size;
    }
}

pub fn generate_il2cpp_h(
    bin: &BinaryImage,
    meta: &Metadata,
    reg: &RegistrationResult,
) -> Result<String> {
    let mut out = String::with_capacity(2 * 1024 * 1024);
    out.push_str(IL2CPP_BASE_TYPES);
    let mut resolver = TypeResolver::new(bin, meta, reg);
    let ptr_sz = bin.ptr_size();
    let box_hdr = (ptr_sz * 2) as i32;
    let mut used_struct_names = HashSet::with_capacity(meta.type_defs.len());

    for (td_idx, td) in meta.type_defs.iter().enumerate() {
        let (root_ns, nested_full) = resolver.resolve_full_typedef_name(td_idx);
        let raw_c = if root_ns.is_empty() {
            nested_full
        } else {
            format!("{}_{}", root_ns, nested_full)
        };
        let base_name = sanitize_c_ident(&raw_c);
        let c_name = alloc_unique_struct_name(&mut used_struct_names, base_name, td_idx);
        let is_val = td.is_valuetype() || td.is_enum();
        let is_open_generic = td.generic_container_index >= 0;

        let _ = writeln!(out, "struct {} {{", c_name);
        let mut instance_fields = Vec::new();
        let mut static_fields = Vec::new();
        if td.field_count > 0 && td.first_field_idx >= 0 {
            let fs = td.first_field_idx as usize;
            let fe = (fs + td.field_count as usize).min(meta.fields.len());

            for (local_i, f) in meta.fields[fs..fe].iter().enumerate() {
                let mut fname = sanitize_c_ident(meta.get_string(f.name_index));
                if fname.is_empty() {
                    fname = format!("field_{}", local_i);
                }
                let raw_t = resolver.read_type_by_index(f.type_index);
                let attrs = raw_t.as_ref().map(|t| t.attrs).unwrap_or(0);
                let ftype = raw_t
                    .as_ref()
                    .map(|t| resolver.format_il2cpp_type(t, 0))
                    .unwrap_or_else(|| "object".to_string());
                let raw_off = read_type_field_offset(bin, reg.field_offsets_table_va, td_idx, local_i);

                if (attrs & 0x50) != 0 {
                    let soff = raw_off.and_then(|o| (o >= 0).then_some(o as usize));
                    static_fields.push((ftype, fname, soff));
                } else if let Some(off) = raw_off.filter(|&o| o >= 0) {
                    let adj = if is_val && off >= box_hdr {
                        (off - box_hdr) as usize
                    } else {
                        off as usize
                    };
                    let (c_type, size) = map_c_type(&ftype, ptr_sz);
                    instance_fields.push(StructFieldEntry {
                        offset: adj,
                        c_type,
                        size,
                        name: fname,
                        raw_type: ftype,
                    });
                } else {
                    static_fields.push((ftype, fname, None));
                }
            }
        }
        emit_padded_struct_fields(&mut out, instance_fields, &static_fields, is_open_generic);
        out.push_str("};\n\n");
    }

    Ok(out)
}

pub fn generate_adaptive_il2cpp_h(
    meta: &AdaptiveMetadata,
    resolver: &AdaptiveTypeResolver,
    field_offsets: &HashMap<usize, Vec<u32>>,
) -> Result<String> {
    let mut out = String::with_capacity(2 * 1024 * 1024);
    out.push_str(IL2CPP_BASE_TYPES);
    let ptr_sz = resolver.bin.ptr_size();
    let mut used_struct_names = HashSet::with_capacity(meta.types.len());

    for td in &meta.types {
        let raw = if td.fullname.is_empty() {
            td.name.as_str()
        } else {
            td.fullname.as_str()
        };
        let base_name = sanitize_c_ident(raw);
        let c_name = alloc_unique_struct_name(&mut used_struct_names, base_name, td.index);
        let _ = writeln!(out, "struct {} {{", c_name);
        let mut instance_fields = Vec::new();
        let mut static_fields = Vec::new();
        if td.field_count > 0 {
            let fs = td.field_start;
            let fe = (fs + td.field_count as usize).min(meta.fields.len());
            let td_offsets = field_offsets.get(&td.index);

            for (local_i, f) in meta.fields[fs..fe].iter().enumerate() {
                let mut fname = sanitize_c_ident(&f.name);
                if fname.is_empty() {
                    fname = format!("field_{}", local_i);
                }
                let info = resolver.resolve_field_type(f.type_idx_raw);
                let display_type = if info.resolved {
                    info.type_name.as_str()
                } else {
                    infer_field_type_by_name(&f.name)
                };
                let off_opt = td_offsets
                    .and_then(|v| v.get(local_i).copied())
                    .filter(|&o| o != u32::MAX);

                if info.is_static || off_opt.is_none() {
                    static_fields.push((
                        display_type.to_string(),
                        fname,
                        off_opt.map(|o| o as usize),
                    ));
                } else if let Some(off) = off_opt {
                    let (c_type, size) = map_c_type(display_type, ptr_sz);
                    instance_fields.push(StructFieldEntry {
                        offset: off as usize,
                        c_type,
                        size,
                        name: fname,
                        raw_type: display_type.to_string(),
                    });
                }
            }
        }
        emit_padded_struct_fields(&mut out, instance_fields, &static_fields, false);
        out.push_str("};\n\n");
    }

    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_padded_struct_layout_and_clamping() {
        let mut out = String::new();
        let fields = vec![
            StructFieldEntry {
                offset: 0x10,
                c_type: "int32_t",
                size: 4,
                name: "hp".into(),
                raw_type: "int".into(),
            },
            StructFieldEntry {
                offset: 0x10,
                c_type: "int32_t",
                size: 4,
                name: "hp".into(),
                raw_type: "int".into(),
            },
            StructFieldEntry {
                offset: 0x20,
                c_type: "Il2CppVector3",
                size: 12,
                name: "pos".into(),
                raw_type: "Vector3".into(),
            },
            StructFieldEntry {
                offset: 0x28,
                c_type: "float",
                size: 4,
                name: "speed".into(),
                raw_type: "float".into(),
            },
        ];
        let statics = vec![("int".to_string(), "MaxHp".to_string(), Some(0))];
        emit_padded_struct_fields(&mut out, fields, &statics, false);
        assert!(out.contains("uint8_t _pad_0x0[0x10];"));
        assert!(out.contains("int32_t hp;"));
        assert!(out.contains("[overlap @ 0x10]"));
        assert!(out.contains("uint8_t _pad_0x14[0xC];"));
        assert!(out.contains("uint8_t pos[0x8];"));
        assert!(out.contains("float speed;"));
        assert!(out.contains("// static /* int */ MaxHp; // 0x0"));

        let mut empty_out = String::new();
        emit_padded_struct_fields(&mut empty_out, Vec::new(), &[], false);
        assert!(empty_out.contains("uint8_t _empty;"));

        let mut gen_out = String::new();
        let gen_fields = vec![
            StructFieldEntry {
                offset: 0,
                c_type: "void*",
                size: 8,
                name: "a".into(),
                raw_type: "T".into(),
            },
            StructFieldEntry {
                offset: 0,
                c_type: "void*",
                size: 8,
                name: "b".into(),
                raw_type: "U".into(),
            },
        ];
        emit_padded_struct_fields(&mut gen_out, gen_fields, &[], true);
        assert!(gen_out.contains("open generic template"));
        assert!(!gen_out.contains("[overlap"));

        let mut used = HashSet::new();
        assert_eq!(alloc_unique_struct_name(&mut used, "__c".into(), 10), "__c");
        assert_eq!(alloc_unique_struct_name(&mut used, "__c".into(), 42), "__c_42");
    }
}
